begin;
set local role postgres;
create extension if not exists pgtap with schema extensions;
set local search_path=pgtap,extensions,public;
select plan(38);
select has_table('public','payments','shared payments table exists');
select has_table('public','payment_allocations','authoritative allocations table exists');
select has_table('public','payment_accounts','settlement accounts table exists');
select has_table('public','customer_refunds','refund table exists');
select has_function('public','post_customer_payment',array['uuid','uuid','uuid','date','text','numeric','numeric','uuid','uuid','text','text','jsonb','uuid'],'customer payment RPC exists');
select has_function('public','post_supplier_payment',array['uuid','uuid','uuid','date','text','numeric','numeric','uuid','uuid','text','text','jsonb','uuid'],'supplier payment RPC exists');
select has_function('public','allocate_customer_credit',array['uuid','uuid','uuid','numeric'],'customer credit allocation RPC exists');
select has_function('public','allocate_supplier_credit',array['uuid','uuid','uuid','numeric'],'supplier credit allocation RPC exists');
select has_function('public','update_payment_method',array['uuid','uuid','text','text','boolean','boolean','boolean'],'payment method lifecycle RPC exists');
select has_view('public','customer_unapplied_credit_documents','unapplied cash and Credit Note view exists');

insert into auth.users(id,instance_id,aud,role,email,encrypted_password,email_confirmed_at,created_at,updated_at) values
('00000000-0000-4000-8000-00000000600a','00000000-0000-0000-0000-000000000000','authenticated','authenticated','payments-owner@example.test','',now(),now(),now()),
('00000000-0000-4000-8000-00000000600b','00000000-0000-0000-0000-000000000000','authenticated','authenticated','payments-outsider@example.test','',now(),now(),now());
set local role authenticated;select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-00000000600a","role":"authenticated"}',true);
select lives_ok($$select public.create_organization('Payments Test','payments-test','GB','GBP','Europe/London')$$,'payment tenant bootstraps');
set local role postgres;
select set_config('x.org',(select id::text from public.organizations where slug='payments-test'),true);
select set_config('x.business',(select id::text from public.businesses where organization_id=current_setting('x.org')::uuid limit 1),true);
insert into public.branches(id,organization_id,business_id,name,code,status,timezone,created_by) values
('00000000-0000-4000-8000-000000006101',current_setting('x.org')::uuid,current_setting('x.business')::uuid,'Main Branch','PAY1','active','Europe/London','00000000-0000-4000-8000-00000000600a'),
('00000000-0000-4000-8000-000000006102',current_setting('x.org')::uuid,current_setting('x.business')::uuid,'Other Branch','PAY2','active','Europe/London','00000000-0000-4000-8000-00000000600a');
insert into public.customers(id,organization_id,customer_code,customer_type,display_name,default_currency,created_by) values('00000000-0000-4000-8000-000000006201',current_setting('x.org')::uuid,'PAY-CUS','BUSINESS','Payment Customer','GBP','00000000-0000-4000-8000-00000000600a');
insert into public.suppliers(id,organization_id,supplier_code,supplier_type,legal_name,default_currency,created_by) values('00000000-0000-4000-8000-000000006301',current_setting('x.org')::uuid,'PAY-SUP','DISTRIBUTOR','Payment Supplier','GBP','00000000-0000-4000-8000-00000000600a');
insert into public.customer_invoices(id,organization_id,business_id,invoice_number,customer_id,branch_id,invoice_date,due_date,currency,exchange_rate,base_currency,customer_name_snapshot,subtotal,total,base_currency_total,status,idempotency_key,request_hash,created_by,issued_by,issued_at) values
('00000000-0000-4000-8000-000000006401',current_setting('x.org')::uuid,current_setting('x.business')::uuid,'PAY-INV-1','00000000-0000-4000-8000-000000006201','00000000-0000-4000-8000-000000006101',current_date,current_date+30,'GBP',1,'GBP','Payment Customer',100,100,100,'ISSUED','00000000-0000-4000-8000-000000006411','test-1','00000000-0000-4000-8000-00000000600a','00000000-0000-4000-8000-00000000600a',now()),
('00000000-0000-4000-8000-000000006402',current_setting('x.org')::uuid,current_setting('x.business')::uuid,'PAY-INV-2','00000000-0000-4000-8000-000000006201','00000000-0000-4000-8000-000000006101',current_date,current_date+30,'GBP',1,'GBP','Payment Customer',150,150,150,'ISSUED','00000000-0000-4000-8000-000000006412','test-2','00000000-0000-4000-8000-00000000600a','00000000-0000-4000-8000-00000000600a',now());
insert into public.supplier_invoices(id,organization_id,supplier_id,invoice_number,invoice_date,due_date,currency,exchange_rate,base_currency,subtotal,total,base_currency_total,status,match_status,created_by,approved_by,approved_at) values
('00000000-0000-4000-8000-000000006501',current_setting('x.org')::uuid,'00000000-0000-4000-8000-000000006301','SUP-PAY-1',current_date,current_date+30,'GBP',1,'GBP',100,100,100,'APPROVED','MATCHED','00000000-0000-4000-8000-00000000600a','00000000-0000-4000-8000-00000000600a',now()),
('00000000-0000-4000-8000-000000006502',current_setting('x.org')::uuid,'00000000-0000-4000-8000-000000006301','SUP-PAY-2',current_date,current_date+30,'GBP',1,'GBP',150,150,150,'APPROVED','MATCHED','00000000-0000-4000-8000-00000000600a','00000000-0000-4000-8000-00000000600a',now());
set local role authenticated;select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-00000000600a","role":"authenticated"}',true);
select set_config('x.account',(select public.create_payment_account(current_setting('x.org')::uuid,'00000000-0000-4000-8000-000000006101','BANK-GBP','Main Bank','BANK','GBP','Operational settlement')::text),true);
select set_config('x.method',(select public.create_payment_method(current_setting('x.org')::uuid,'00000000-0000-4000-8000-000000006101',current_setting('x.account')::uuid,'TRANSFER','Bank transfer','BANK_TRANSFER',true,true,false)::text),true);
select is((select account_type from public.payment_accounts where id=current_setting('x.account')::uuid),'BANK','settlement account configured');
select set_config('x.cpay1',(select public.post_customer_payment(current_setting('x.org')::uuid,'00000000-0000-4000-8000-000000006201','00000000-0000-4000-8000-000000006101',current_date,'GBP',1,50,current_setting('x.method')::uuid,current_setting('x.account')::uuid,'CREF-1','Partial',jsonb_build_array(jsonb_build_object('invoice_id','00000000-0000-4000-8000-000000006401','amount',40)),'00000000-0000-4000-8000-000000006601')->>'payment_id'),true);
select is((select status from public.customer_invoices where id='00000000-0000-4000-8000-000000006401'),'PARTIALLY_PAID','partial customer allocation updates invoice state');
select is((select outstanding_base from public.customer_invoice_settlement where id='00000000-0000-4000-8000-000000006401'),60::numeric,'partial allocation reduces AR');
select lives_ok(format($q$select public.allocate_existing_payment('%s','%s',jsonb_build_array(jsonb_build_object('invoice_id','00000000-0000-4000-8000-000000006401','amount',10)))$q$,current_setting('x.org'),current_setting('x.cpay1')),'additional allocation RPC works');
select set_config('x.cpay2',(select public.post_customer_payment(current_setting('x.org')::uuid,'00000000-0000-4000-8000-000000006201','00000000-0000-4000-8000-000000006101',current_date,'GBP',1,70,current_setting('x.method')::uuid,current_setting('x.account')::uuid,'CREF-2','Final and unapplied',jsonb_build_array(jsonb_build_object('invoice_id','00000000-0000-4000-8000-000000006401','amount',50)),'00000000-0000-4000-8000-000000006602')->>'payment_id'),true);
select is((select status from public.customer_invoices where id='00000000-0000-4000-8000-000000006401'),'PAID','full customer allocation marks invoice paid');
select is((select outstanding_base from public.customer_receivables where customer_id='00000000-0000-4000-8000-000000006201'),150::numeric,'derived AR reflects payment settlement');
select is((select unapplied_amount from public.customer_unapplied_credits where payment_id=current_setting('x.cpay2')::uuid),20::numeric,'customer overpayment remains unapplied credit');
select is((public.post_customer_payment(current_setting('x.org')::uuid,'00000000-0000-4000-8000-000000006201','00000000-0000-4000-8000-000000006101',current_date,'GBP',1,70,current_setting('x.method')::uuid,current_setting('x.account')::uuid,'CREF-2','Final and unapplied',jsonb_build_array(jsonb_build_object('invoice_id','00000000-0000-4000-8000-000000006401','amount',50)),'00000000-0000-4000-8000-000000006602')->>'replayed')::boolean,true,'same idempotency payload replays');
select throws_ok(format($q$select public.post_customer_payment('%s','00000000-0000-4000-8000-000000006201','00000000-0000-4000-8000-000000006101',current_date,'GBP',1,81,'%s','%s','CREF-X','Changed','[]','00000000-0000-4000-8000-000000006602')$q$,current_setting('x.org'),current_setting('x.method'),current_setting('x.account')),'P0001','IDEMPOTENCY_CONFLICT','changed idempotency payload rejected');
select throws_ok(format($q$select public.post_customer_payment('%s','00000000-0000-4000-8000-000000006201','00000000-0000-4000-8000-000000006101',current_date,'GBP',1,70,'%s','%s','CREF-2','Duplicate','[]',gen_random_uuid())$q$,current_setting('x.org'),current_setting('x.method'),current_setting('x.account')),'P0001','DUPLICATE_PAYMENT_REFERENCE','duplicate external reference blocked per tenant and method');
select throws_ok(format($q$select public.allocate_existing_payment('%s','%s',jsonb_build_array(jsonb_build_object('invoice_id','00000000-0000-4000-8000-000000006402','amount',100)))$q$,current_setting('x.org'),current_setting('x.cpay2')),'P0001','PAYMENT_ALLOCATION_EXCEEDS_PAYMENT','payment over-allocation blocked');
select set_config('x.refund',(select public.post_customer_refund(current_setting('x.org')::uuid,'00000000-0000-4000-8000-000000006201','00000000-0000-4000-8000-000000006101',current_setting('x.cpay2')::uuid,null,current_date,'GBP',1,20,current_setting('x.method')::uuid,current_setting('x.account')::uuid,'RF-EXT','Return unapplied credit','00000000-0000-4000-8000-000000006701')->>'refund_id'),true);
select is((select status from public.customer_refunds where id=current_setting('x.refund')::uuid),'POSTED','eligible customer refund posts');
select throws_ok(format($q$select public.post_customer_refund('%s','00000000-0000-4000-8000-000000006201','00000000-0000-4000-8000-000000006101','%s',null,current_date,'GBP',1,1,'%s','%s','RF-OVER','Too much',gen_random_uuid())$q$,current_setting('x.org'),current_setting('x.cpay2'),current_setting('x.method'),current_setting('x.account')),'P0001','REFUND_EXCEEDS_AVAILABLE_CREDIT','refund cannot exceed available credit');
select set_config('x.spay1',(select public.post_supplier_payment(current_setting('x.org')::uuid,'00000000-0000-4000-8000-000000006301','00000000-0000-4000-8000-000000006101',current_date,'GBP',1,40,current_setting('x.method')::uuid,current_setting('x.account')::uuid,'SREF-1','Partial supplier',jsonb_build_array(jsonb_build_object('invoice_id','00000000-0000-4000-8000-000000006501','amount',40)),'00000000-0000-4000-8000-000000006801')->>'payment_id'),true);
select is((select status from public.supplier_invoices where id='00000000-0000-4000-8000-000000006501'),'PARTIALLY_PAID','supplier partial payment updates status');
select is((select outstanding_base from public.supplier_payables where supplier_id='00000000-0000-4000-8000-000000006301'),210::numeric,'derived AP reflects partial payment');
select set_config('x.spay2',(select public.post_supplier_payment(current_setting('x.org')::uuid,'00000000-0000-4000-8000-000000006301','00000000-0000-4000-8000-000000006101',current_date,'GBP',1,100,current_setting('x.method')::uuid,current_setting('x.account')::uuid,'SREF-2','Final plus advance',jsonb_build_array(jsonb_build_object('invoice_id','00000000-0000-4000-8000-000000006501','amount',60)),'00000000-0000-4000-8000-000000006802')->>'payment_id'),true);
select is((select status from public.supplier_invoices where id='00000000-0000-4000-8000-000000006501'),'PAID','supplier invoice reaches paid');
select is((select unapplied_amount from public.supplier_advances where payment_id=current_setting('x.spay2')::uuid),40::numeric,'supplier advance remains unapplied');
select set_config('x.reversal',(select public.reverse_payment(current_setting('x.org')::uuid,current_setting('x.spay1')::uuid,'Entry correction','00000000-0000-4000-8000-000000006901')->>'payment_id'),true);
select is((select status from public.payments where id=current_setting('x.spay1')::uuid),'VOIDED','original supplier payment preserved as voided');
select is((select outstanding_base from public.supplier_invoice_settlement where id='00000000-0000-4000-8000-000000006501'),40::numeric,'reversal restores supplier liability');
select throws_ok(format($q$select public.reverse_payment('%s','%s','Again',gen_random_uuid())$q$,current_setting('x.org'),current_setting('x.spay1')),'P0001','PAYMENT_ALREADY_REVERSED','double reversal blocked');
select throws_ok(format($q$update public.payments set amount=1 where id='%s'$q$,current_setting('x.cpay1')),'42501',null,'direct posted payment mutation blocked');
select throws_ok(format($q$select public.post_customer_payment('%s','00000000-0000-4000-8000-000000006201','00000000-0000-4000-8000-000000006102',current_date,'GBP',1,10,'%s','%s','CREF-BRANCH','Wrong branch','[]',gen_random_uuid())$q$,current_setting('x.org'),current_setting('x.method'),current_setting('x.account')),'P0001','PAYMENT_METHOD_INACTIVE','branch-restricted payment method cannot be used elsewhere');
select set_config('x.otherorg',(select public.create_organization('Payments Other','payments-other','GB','GBP','Europe/London')::text),true);
select throws_ok(format($q$select public.post_customer_payment('%s','00000000-0000-4000-8000-000000006201','00000000-0000-4000-8000-000000006101',current_date,'GBP',1,10,'%s','%s','CROSS','Cross tenant','[]',gen_random_uuid())$q$,current_setting('x.otherorg'),current_setting('x.method'),current_setting('x.account')),'P0001','PAYMENT_METHOD_INACTIVE','cross-tenant payment references rejected');
set local role authenticated;select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-00000000600b","role":"authenticated"}',true);
select throws_ok(format($q$select public.post_customer_payment('%s','00000000-0000-4000-8000-000000006201','00000000-0000-4000-8000-000000006101',current_date,'GBP',1,10,'%s','%s','NOAUTH','No permission','[]',gen_random_uuid())$q$,current_setting('x.org'),current_setting('x.method'),current_setting('x.account')),'42501','PERMISSION_DENIED','unauthorized payment posting rejected');
set local role anon;select set_config('request.jwt.claims','{"role":"anon"}',true);
select throws_ok(format($q$select public.reverse_payment('%s','%s','Anon',gen_random_uuid())$q$,current_setting('x.org'),current_setting('x.cpay1')),'42501',null,'anon cannot invoke payment reversal');
set local role postgres;
select is((select count(*) from information_schema.columns where table_schema='public' and table_name in('payments','customer_refunds') and column_name in('card_number','cvv','pin','magnetic_stripe')),0::bigint,'no prohibited card-secret columns exist');
select is((select count(*) from public.audit_events where organization_id=current_setting('x.org')::uuid and action like 'payments.%')>5,true,'payment lifecycle is audited');
select * from finish();rollback;
